(function(){
'use strict';
const api=window.CeylonPlanner,modal=document.querySelector('#journey-planner'),screen=modal.querySelector('.planner-screen'),next=modal.querySelector('.planner-next'),back=modal.querySelector('.planner-back'),navigation=modal.querySelector('.planner-navigation'),error=modal.querySelector('.planner-error'),storageKey='ceylon-voyagers-journey-v1';
const steps=['Your time','Your interests','Your experiences','Your travel style','Your wish list'];
const defaults=()=>({days:7,startDate:'',interests:[],experiences:[],adults:2,children:0,pace:'balanced',stay:'boutique',notes:''});let prefs=defaults(),step=0,plan=null,completed=false,storageAvailable=true;
const esc=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const known=(keys,list)=>Array.isArray(keys)?[...new Set(keys.filter(k=>list.some(x=>x[0]===k)))]:[];
function restore(){try{const saved=JSON.parse(localStorage.getItem(storageKey)||'null');if(!saved||saved.version!==1)return;const p=saved.preferences||{};prefs={...defaults(),days:Math.max(2,Math.min(21,Number.isInteger(p.days)?p.days:7)),startDate:/^\d{4}-\d{2}-\d{2}$/.test(p.startDate||'')?p.startDate:'',interests:known(p.interests,api.interests),experiences:known(p.experiences,api.experiences),adults:Math.max(1,Math.min(12,Number.isInteger(p.adults)?p.adults:2)),children:Math.max(0,Math.min(6,Number.isInteger(p.children)?p.children:0)),pace:['slow','balanced','active'].includes(p.pace)?p.pace:'balanced',stay:['simple','boutique','premium'].includes(p.stay)?p.stay:'boutique',notes:typeof p.notes==='string'?p.notes.slice(0,700):''};step=Math.max(0,Math.min(4,Number.isInteger(saved.step)?saved.step:0));completed=!!saved.completed;if(completed){try{plan=api.makePlan(prefs);}catch{completed=false;step=0;}}}catch{storageAvailable=false;}}
function save(){try{localStorage.setItem(storageKey,JSON.stringify({version:1,preferences:prefs,step,completed}));modal.querySelector('.planner-save-status').textContent='Draft saved in this browser';storageAvailable=true;}catch{storageAvailable=false;modal.querySelector('.planner-save-status').textContent='Download your plan to keep a copy';}}
const labelFor=(key,options)=>options.find(o=>o[0]===key)?.[1]||key;
function syncSidebar(){modal.querySelector('.planner-step-list').innerHTML=steps.map((name,i)=>'<li class="'+(completed?'done':i===step?'active':i<step?'done':'')+'"'+(!completed&&i===step?' aria-current="step"':'')+'><span>'+(completed||i<step?'✓':i+1)+'</span>'+name+'</li>').join('');modal.querySelector('.planner-sidebar-summary').innerHTML='<strong>'+esc(prefs.days)+' days / '+esc(Number(prefs.days)-1)+' nights</strong>'+esc(prefs.adults)+' adults'+(prefs.children?' · '+esc(prefs.children)+(prefs.children===1?' child':' children'):'')+'<br>'+esc(prefs.interests.length)+' interests · '+esc(prefs.experiences.length)+' experiences';modal.querySelector('.planner-progress>span').style.width=(completed?100:(step+1)*20)+'%';modal.querySelector('.planner-step-count').textContent='Step '+(step+1)+' of 5';}
function showError(message){error.hidden=false;error.textContent=message;error.scrollIntoView({block:'nearest',behavior:'smooth'});}
function clearError(){error.hidden=true;error.textContent='';}
function choice(option,kind){const selected=prefs[kind].includes(option[0]);return'<button type="button" class="planner-choice" data-choice="'+kind+'" data-value="'+option[0]+'" aria-pressed="'+selected+'">'+(option[3]?'<span class="planner-choice-icon" aria-hidden="true">'+option[3]+'</span>':'')+'<span class="planner-choice-copy"><strong>'+esc(option[1])+'</strong><small>'+esc(option[2])+'</small></span><span class="planner-choice-check" aria-hidden="true">✓</span></button>';}
function radioChoice(key,title,description,kind){return'<button type="button" class="planner-choice" data-single="'+kind+'" data-value="'+key+'" aria-pressed="'+(prefs[kind]===key)+'"><span class="planner-choice-copy"><strong>'+title+'</strong><small>'+description+'</small></span></button>';}
const stepIntro=(kicker,title,description)=>'<p class="planner-kicker">'+kicker+'</p><h3 tabindex="-1">'+title+'</h3><p class="planner-lead">'+description+'</p>';
function render(focus=true){clearError();syncSidebar();navigation.hidden=completed;if(completed){renderResult();return;}back.hidden=step===0;next.disabled=false;next.innerHTML=step===4?'Build my journey <span>↗</span>':'Continue <span>→</span>';let html='';
if(step===0){html=stepIntro('FIRST, A LITTLE TIME','How long is your island escape?','Choose your total time in Sri Lanka, including arrival and departure days. We’ll leave room for travel and rest.')+'<div class="planner-days"><label for="planner-days">Days in Sri Lanka<small>2–21 days · '+(prefs.days-1)+' nights</small></label><div class="planner-day-counter"><button type="button" data-day-change="-1" aria-label="One fewer day">−</button><input id="planner-days" type="number" min="2" max="21" step="1" value="'+esc(prefs.days)+'" aria-label="Days in Sri Lanka"><button type="button" data-day-change="1" aria-label="One more day">+</button></div></div><div class="planner-presets" aria-label="Popular trip lengths">'+[5,7,10,14,21].map(d=>'<button type="button" data-days="'+d+'" class="'+(prefs.days===d?'selected':'')+'">'+d+' days</button>').join('')+'</div><label class="planner-date-field">Arrival date <span>(optional)</span><input id="planner-start-date" type="date" value="'+esc(prefs.startDate)+'"><small>Not sure yet? Leave this blank for a flexible plan.</small></label><div class="planner-info"><span aria-hidden="true">↗</span><div>Your route starts and finishes at Colombo airport. The final night stays near the airport, so your departure day has breathing room.</div></div>';}
if(step===1){html=stepIntro('FOLLOW WHAT MOVES YOU','What draws you to Sri Lanka?','Pick as many as you like. A shorter trip may focus on fewer regions so you can enjoy the places you visit.')+'<div class="planner-choice-grid" role="group" aria-label="Travel interests">'+api.interests.map(o=>choice(o,'interests')).join('')+'</div><p class="planner-remaining-note">Select at least one interest. You can change your choices later.</p>';}
if(step===2){html=stepIntro('THE MOMENTS IN BETWEEN','What would you love to experience?','Choose your wish list. We’ll fit what makes sense into your route and tell you if something needs more time.')+'<div class="planner-choice-grid" role="group" aria-label="Preferred experiences">'+api.experiences.map(o=>choice(o,'experiences')).join('')+'</div><p class="planner-remaining-note">Select at least one. Activities are suggestions; availability and suitability are confirmed during planning.</p>';}
if(step===3){html=stepIntro('MAKE IT FEEL LIKE YOU','Who’s coming, and how do you travel?','Set your pace and the kind of stay you enjoy. These preferences shape the draft, without locking you into a booking.')+'<div class="planner-fields-row"><label>Adults<input id="planner-adults" type="number" min="1" max="12" step="1" value="'+esc(prefs.adults)+'" required></label><label>Children<input id="planner-children" type="number" min="0" max="6" step="1" value="'+esc(prefs.children)+'" required></label></div><span class="planner-group-label">Your travel pace</span><div class="planner-pace-grid" role="group" aria-label="Travel pace">'+radioChoice('slow','Slow & easy','Fewer stops. Free afternoons.','pace')+radioChoice('balanced','A little of both','Explore, with room to pause.','pace')+radioChoice('active','Out & about','More exploring each day.','pace')+'</div><span class="planner-group-label">Your stay style</span><div class="planner-pace-grid" role="group" aria-label="Stay preference">'+radioChoice('simple','Simple comfort','Guesthouses and easy stays.','stay')+radioChoice('boutique','A sense of place','Small hotels and boutique stays.','stay')+radioChoice('premium','Extra comfort','Premium stays to explore.','stay')+'</div><div class="planner-info"><span aria-hidden="true">✳</span><div>Travelling with children or need a gentler pace? This draft is a starting point. Add ages, walking needs, or anything that matters in the next step so arrangements can be checked.</div></div>';}
if(step===4){html=stepIntro('YOUR WISH LIST, TOGETHER','Ready to give your journey a shape?','Review your preferences. We’ll use these to build a suggested route and a day-by-day plan.')+'<div class="planner-review"><article><small>YOUR TIME</small><p>'+prefs.days+' days / '+(prefs.days-1)+' nights<br>'+esc(prefs.startDate||'Flexible arrival date')+'</p></article><article><small>YOUR TRAVEL STYLE</small><p>'+prefs.adults+' adults · '+prefs.children+' children<br>'+esc(prefs.pace)+' pace · '+esc(prefs.stay)+' stays</p></article><article><small>YOUR INTERESTS</small><p>'+prefs.interests.map(k=>esc(labelFor(k,api.interests))).join(' · ')+'</p></article><article><small>YOUR EXPERIENCES</small><p>'+prefs.experiences.map(k=>esc(labelFor(k,api.experiences))).join(' · ')+'</p></article></div><label class="planner-notes">Anything else on your mind? <span>(optional)</span><textarea id="planner-notes" maxlength="700" rows="3" placeholder="A place you dream of, children’s ages, walking preferences, or a special occasion…">'+esc(prefs.notes)+'</textarea></label><div class="planner-info"><span aria-hidden="true">◎</span><div>This planner makes a suggested route from your preferences. Your notes are saved with the plan for personal review; they do not automatically change the route. No booking or payment is made.</div></div>';}
screen.innerHTML=html;if(focus)screen.querySelector('h3')?.focus({preventScroll:true});}
function readFields(){if(step===0){const days=screen.querySelector('#planner-days'),date=screen.querySelector('#planner-start-date');if(!days.reportValidity())return false;if(!date.reportValidity())return false;prefs.days=Number(days.value);prefs.startDate=date.value;}if(step===3){for(const [id,key] of [['planner-adults','adults'],['planner-children','children']]){const input=screen.querySelector('#'+id);if(!input.reportValidity())return false;prefs[key]=Number(input.value);}}if(step===4)prefs.notes=screen.querySelector('#planner-notes').value.slice(0,700);return true;}
function validateStep(){if(!readFields())return false;if(step===1&&!prefs.interests.length){showError('Choose at least one interest to help shape your journey.');return false;}if(step===2&&!prefs.experiences.length){showError('Choose at least one experience for your wish list.');return false;}return true;}
next.onclick=()=>{clearError();if(!validateStep())return;if(step<4){step++;save();render();modal.querySelector('.planner-main').scrollIntoView({block:'start'});}else{try{next.disabled=true;plan=api.makePlan(prefs);completed=true;save();render();modal.scrollTop=0;}catch(e){next.disabled=false;showError(e.message||'Please check your preferences and try again.');}}};back.onclick=()=>{readFields();step=Math.max(0,step-1);save();render();};
screen.addEventListener('click',event=>{const button=event.target.closest('button');if(!button)return;if(button.dataset.choice){const kind=button.dataset.choice,key=button.dataset.value;const index=prefs[kind].indexOf(key);if(index>=0)prefs[kind].splice(index,1);else prefs[kind].push(key);button.setAttribute('aria-pressed',String(prefs[kind].includes(key)));clearError();save();syncSidebar();}if(button.dataset.single){const kind=button.dataset.single;prefs[kind]=button.dataset.value;screen.querySelectorAll('[data-single="'+kind+'"]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.value===prefs[kind])));save();}if(button.dataset.days||button.dataset.dayChange){const input=screen.querySelector('#planner-days');const value=button.dataset.days?Number(button.dataset.days):Math.max(2,Math.min(21,(Number(input.value)||7)+Number(button.dataset.dayChange)));prefs.days=value;const date=screen.querySelector('#planner-start-date');if(date)prefs.startDate=date.value;save();render(false);syncSidebar();screen.querySelector('#planner-days').focus({preventScroll:true});}});
screen.addEventListener('input',event=>{const id=event.target.id;if(id==='planner-days'){const n=Number(event.target.value);if(Number.isInteger(n)&&n>=2&&n<=21){prefs.days=n;screen.querySelector('.planner-days label small').textContent='2–21 days · '+(n-1)+' nights';screen.querySelectorAll('[data-days]').forEach(b=>b.classList.toggle('selected',Number(b.dataset.days)===n));}}else if(id==='planner-start-date')prefs.startDate=event.target.value;else if(id==='planner-adults')prefs.adults=Number(event.target.value);else if(id==='planner-children')prefs.children=Number(event.target.value);else if(id==='planner-notes')prefs.notes=event.target.value.slice(0,700);else return;save();syncSidebar();});
function resultStatus(message){const status=screen.querySelector('.planner-result-status');if(status)status.textContent=message;}
function renderResult(){if(!plan)return;const p=plan.preferences;screen.innerHTML=stepIntro('THIS ONE STARTS WITH YOU','Your journey, taking shape.','A suggested plan built around the time you have and the things you love. Review it, make changes, and keep a copy.')+'<div class="planner-result-summary"><strong>'+esc(plan.title)+'</strong><p>'+p.days+' days / '+(p.days-1)+' nights · '+p.adults+' adults'+(p.children?' · '+p.children+(p.children===1?' child':' children'):'')+' · '+esc(p.pace)+' pace</p><div class="planner-result-tags">'+p.interests.map(k=>'<span>'+esc(labelFor(k,api.interests))+'</span>').join('')+'</div></div><div class="planner-result-actions"><button type="button" class="planner-primary" data-plan-action="inquiry">Add plan to inquiry ↗</button><button type="button" data-plan-action="download">Download plan ↓</button><button type="button" data-plan-action="edit">Edit preferences</button><button type="button" data-plan-action="save">Save draft</button></div><p class="planner-result-status" role="status">'+(storageAvailable?'Your draft is saved in this browser. Download a copy to take it with you.':'Download a copy to keep your plan.')+'</p><h4 class="planner-result-heading">Your island route</h4><div class="planner-route-strip">'+plan.route.map(r=>'<div class="planner-base"><img src="'+r.image+'" alt="" loading="lazy"><span>'+esc(r.name)+'<small>'+r.nights+' night'+(r.nights===1?'':'s')+'</small></span></div>').join('')+'</div><p class="planner-remaining-note">Starts and finishes at Colombo airport. '+esc(plan.stayNote)+'</p><h4 class="planner-result-heading">One day at a time.</h4>'+plan.days.map(d=>'<details class="planner-day"'+(d.day===1?' open':'')+'><summary><span class="planner-day-number">DAY '+String(d.day).padStart(2,'0')+'</span><span class="planner-day-title">'+esc(d.place)+'<small>'+esc(d.date|| (d.transfer?'Arrival / travel day':'Explore at your pace'))+'</small></span><b aria-hidden="true">+</b></summary><div class="planner-day-body"><article><h5>Morning · '+esc(d.morning.title)+'</h5><p>'+esc(d.morning.detail)+'</p></article><article><h5>Afternoon · '+esc(d.afternoon.title)+'</h5><p>'+esc(d.afternoon.detail)+'</p></article><p class="planner-overnight">'+(d.overnight?'Overnight · '+esc(d.overnight):'Your journey comes full circle.')+'</p></div></details>').join('')+'<div class="planner-result-notes"><h4>A little planning perspective</h4><ul>'+plan.warnings.map(w=>'<li>'+esc(w)+'</li>').join('')+'</ul>'+(p.notes?'<p><strong>Your notes:</strong> '+esc(p.notes)+'</p>':'')+'</div>';screen.querySelectorAll('[data-plan-action]').forEach(button=>button.onclick=()=>{const action=button.dataset.planAction;if(action==='edit'){completed=false;step=0;save();render();modal.scrollTop=0;}if(action==='save'){save();resultStatus(storageAvailable?'Saved. Your plan will be here in this browser when you return.':'This browser could not save your plan. Use Download plan to keep a copy.');}if(action==='download'){const url=URL.createObjectURL(new Blob([api.toText(plan)],{type:'text/plain;charset=utf-8'})),link=document.createElement('a');link.href=url;link.download='ceylon-voyagers-my-journey.txt';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);resultStatus('Your journey draft has been downloaded. No booking has been made.');}if(action==='inquiry'){const field=document.querySelector('#inquiry textarea[name="message"]'),text=api.toText(plan);field.value=text;const date=document.querySelector('#inquiry input[name="date"]');if(p.startDate)date.value=p.startDate;document.querySelector('#inquiry select[name="interest"]').selectedIndex=0;closePlanner();document.querySelector('#inquiry').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});field.focus({preventScroll:true});document.querySelector('#form-status').textContent='Your journey plan is added below. Complete your contact details to download your inquiry draft; it has not been sent.';}});screen.querySelector('h3')?.focus({preventScroll:true});}
function openPlanner(){render(false);modal.showModal();document.body.classList.add('planner-is-open');screen.querySelector('h3')?.focus({preventScroll:true});}
function closePlanner(){if(!completed)readFields();save();modal.close();}
document.querySelector('.build-start').addEventListener('click',openPlanner);modal.querySelector('.planner-close').onclick=closePlanner;modal.addEventListener('close',()=>{document.body.classList.remove('planner-is-open');document.querySelector('.build-start').focus({preventScroll:true});});modal.addEventListener('cancel',()=>{if(!completed)readFields();save();});modal.querySelector('.planner-reset').onclick=()=>{prefs=defaults();step=0;completed=false;plan=null;save();render();modal.scrollTop=0;};restore();
})();
